        'summary_ar' => 'تقص نشأة موسى في بيت فرعون، وفراره إلى مدين، وتكليمه، ثم قصة قارون الذي لم تنفعه كنوزه — وتقرر أن العاقبة للمتقين لا لأهل القوة والثراء.',
    ],
    29 => [
        'meaning_en' => "Al-'Ankabut (The Spider): named after the parable of the spider's house, the frailest of houses, likened to reliance on false gods (verse 41).",
        'summary_en' => "Opens with the law of trial — people are not left to say 'we believe' without being tested — recounts the perseverance of Nuh, Ibrahim, Lut and Shu'ayb, and likens every support taken besides Allah to a spider's fragile web.",
        'meaning_ar' => 'سُمِّيت بمثل بيت العنكبوت، أوهن البيوت، الذي شُبّه به اعتماد المشركين على آلهتهم (الآية 41).',
        'summary_ar' => 'تفتتح بسنّة الابتلاء: لا يُترك الناس أن يقولوا آمنا وهم لا يُفتنون، وتذكر صبر نوح وإبراهيم ولوط وشعيب، وتشبّه كل معتمَد سوى الله ببيت العنكبوت الواهن.',
    ],
    30 => [
        'meaning_en' => 'Ar-Rum (The Romans): named after its opening prophecy that the defeated Romans would be victorious again within a few years.',
        'summary_en' => 'Opens with a fulfilled prophecy of the Roman victory over Persia, then turns to the signs of Allah in creation — the spouses, the heavens, sleep, lightning and the revival of the earth — as proofs of resurrection.',
        'meaning_ar' => 'سُمِّيت بالروم لافتتاحها بنبوءة انتصارهم بعد هزيمتهم في بضع سنين.',
        'summary_ar' => 'تفتتح بنبوءة تحققت بانتصار الروم على الفرس، ثم تعرض آيات الله في الخلق: الأزواج والسماوات والنوم والبرق وإحياء الأرض، دليلاً على البعث.',
    ],
    31 => [
        'meaning_en' => 'Luqman: named after the sage Luqman and his counsel to his son.',
        'summary_en' => "Centers on Luqman's advice to his son — do not associate partners with Allah, be grateful, pray, enjoin good, and walk humbly — framed by proofs of Allah's creation and the limits of human knowledge of the unseen.",
        'meaning_ar' => 'سُمِّيت بلقمان الحكيم ووصاياه لابنه.',
        'summary_ar' => 'محورها وصايا لقمان لابنه: لا تشرك بالله، واشكر، وأقم الصلاة، وأمر بالمعروف، واقصد في مشيك — في إطار دلائل الخلق واختصاص الله بعلم الغيب.',
    ],
    32 => [
        'meaning_en' => 'As-Sajdah (The Prostration): named after the verse of prostration in it (verse 15).',
        'summary_en' => "Affirms revelation, creation in six days, and the stages of man's creation from clay; describes the believers whose sides forsake their beds in night prayer, and what delights are hidden for them.",
        'meaning_ar' => 'سُمِّيت بآية السجدة فيها (الآية 15).',
        'summary_ar' => 'تقرر صدق التنزيل، وخلق السماوات والأرض في ستة أيام، وأطوار خلق الإنسان من طين؛ وتصف المؤمنين الذين تتجافى جنوبهم عن المضاجع، وما أُخفي لهم من قرة أعين.',
    ],
    33 => [
        'meaning_en' => 'Al-Ahzab (The Confederates): named after the confederate armies that besieged Medina in the Battle of the Trench.',
        'summary_en' => "Recounts the Battle of the Trench and the believers' steadfastness, regulates the Prophet's household and the abolition of adoption-based lineage, ordains the hijab, and declares the Prophet the best example for the believers.",
        'meaning_ar' => 'سُمِّيت بالأحزاب الذين تحزبوا على المدينة في غزوة الخندق.',
        'summary_ar' => 'تقص غزوة الأحزاب وثبات المؤمنين، وتنظم شؤون بيت النبوة وإبطال التبني، وتفرض الحجاب، وتقرر أن في رسول الله أسوة حسنة.',
    ],
    34 => [
        'meaning_en' => 'Saba (Sheba): named after the people of Sheba in Yemen and the flood that ruined their dams and gardens (verses 15-17).',
        'summary_en' => 'Contrasts the grateful kingdom of Dawud and Sulayman with the ungrateful people of Sheba whose gardens were swept away, and refutes the deniers of resurrection and the claims of intercession by false gods.',
        'meaning_ar' => 'سُمِّيت بقوم سبأ في اليمن وسيل العرم الذي أهلك جناتهم (الآيات 15-17).',
        'summary_ar' => 'تقابل بين مملكة داود وسليمان الشاكرة وقوم سبأ الكافرين بالنعمة الذين أُرسل عليهم سيل العرم، وترد على منكري البعث ومدّعي شفاعة الآلهة الباطلة.',
    ],
    35 => [
        'meaning_en' => "Fatir (The Originator): named after Allah's attribute as Originator of the heavens and the earth; also called al-Mala'ikah (the Angels).",
        'summary_en' => "Proclaims Allah's power as Creator who appointed angels as messengers, His sustaining of the heavens and earth lest they cease, and divides the inheritors of the Book into wrongdoers, moderates and foremost in good deeds.",
        'meaning_ar' => 'سُمِّيت بفاطر السماوات والأرض، وتسمى أيضاً سورة الملائكة.',
        'summary_ar' => 'تعلن قدرة الله فاطر السماوات والأرض جاعل الملائكة رسلاً، وإمساكه السماوات والأرض أن تزولا، وتقسم ورثة الكتاب إلى ظالم لنفسه ومقتصد وسابق بالخيرات.',
    ],
    36 => [
        'meaning_en' => 'Ya-Sin: named after the two disconnected letters that open it.',
        'summary_en' => "Often called the heart of the Quran: it affirms the Prophet's mission, tells of the city whose people rejected three messengers and the believing man who came running, and argues for resurrection from the dead earth and decaying bones.",
        'meaning_ar' => 'سُمِّيت بالحرفين المقطّعين في أولها (يس).',
        'summary_ar' => 'تقرر رسالة النبي ﷺ، وتقص أصحاب القرية الذين كذبوا ثلاثة مرسلين والرجل المؤمن الذي جاء يسعى، وتستدل على البعث بإحياء الأرض الميتة والعظام الرميم.',
    ],
    37 => [
        'meaning_en' => 'As-Saffat (Those Ranged in Ranks): named after the angels arrayed in ranks, by whom the surah opens with an oath.',
        'summary_en' => "Refutes the pagans' claims about the angels and the jinn, recounts Nuh, Ibrahim's sacrifice of his son and his ransom with a great sacrifice, Musa, Harun, Ilyas, Lut and Yunus, and exalts Allah above what they describe.",
        'meaning_ar' => 'سُمِّيت بالملائكة الصافات صفاً التي افتتحت السورة بالقسم بها.',
        'summary_ar' => 'تبطل مزاعم المشركين في الملائكة والجن، وتقص نوحاً، وذبيحَ إبراهيم وفداءه بذبح عظيم، وموسى وهارون وإلياس ولوطاً ويونس، وتنزه الله عما يصفون.',
    ],
    38 => [
        'meaning_en' => 'Sad: named after the disconnected letter that opens it.',
        'summary_en' => "Answers the leaders of Quraysh who marveled at one God, with the stories of Dawud's judgment and repentance, Sulayman's horses and his trial, Ayyub's relief, and the primordial dispute of Iblis at Adam's creation.",
        'meaning_ar' => 'سُمِّيت بالحرف المقطّع في أولها (ص).',
        'summary_ar' => 'ترد على ملأ قريش الذين عجبوا أن يكون الإله واحداً، بقصص داود في قضائه وأوبته، وسليمان وخيله وفتنته، وكشف الضر عن أيوب، وخصومة إبليس عند خلق آدم.',
    ],
    39 => [
        'meaning_en' => 'Az-Zumar (The Groups): named after the driving of the disbelievers and the believers in groups to Hell and Paradise (verses 71-73).',
        'summary_en' => "A surah of pure devotion to Allah: it commands sincere religion, strikes parables of the one Master, opens the widest door of hope — 'O My servants who have transgressed, do not despair of Allah's mercy' (53) — and ends with the scenes of the two processions.",
        'meaning_ar' => 'سُمِّيت بسَوق الكافرين إلى جهنم زمراً وسَوق المتقين إلى الجنة زمراً (الآيات 71-73).',
        'summary_ar' => 'سورة الإخلاص لله: تأمر بإخلاص الدين، وتضرب الأمثال للمالك الواحد، وتفتح أوسع أبواب الرجاء: «يا عبادي الذين أسرفوا على أنفسهم لا تقنطوا من رحمة الله» (53)، وتختم بمشهد الزمرتين.',
    ],
    40 => [
        'meaning_en' => "Ghafir (The Forgiver): named after Allah's attribute as Forgiver of sin; also called al-Mu'min after the believing man of Pharaoh's house.",
        'summary_en' => "Tells the story of the believer from Pharaoh's family who concealed his faith then spoke out for Musa, warning his people; the surah weaves angels' prayers for the believers with warnings of the Day when hearts reach the throats.",
        'meaning_ar' => 'سُمِّيت بصفة الله غافر الذنب، وتسمى أيضاً سورة المؤمن نسبةً إلى مؤمن آل فرعون.',
        'summary_ar' => 'تقص خبر مؤمن آل فرعون الذي كتم إيمانه ثم صدع بنصرة موسى محذراً قومه؛ وتمزج دعاء الملائكة للمؤمنين بإنذار يوم الآزفة إذ القلوب لدى الحناجر.',
    ],
    41 => [
        'meaning_en' => 'Fussilat (Explained in Detail): named after the description of the Quran as a Book whose verses are explained in detail; also called Ha-Mim as-Sajdah.',
        'summary_en' => "Describes the creation of the heavens and the earth, warns Quraysh of a thunderbolt like that of 'Ad and Thamud, tells how skins will testify against their owners, and teaches repelling evil with what is better, turning enmity into warm friendship.",
        'meaning_ar' => 'سُمِّيت بوصف القرآن: كتاب فُصِّلت آياته، وتسمى أيضاً حم السجدة.',
        'summary_ar' => 'تصف خلق السماوات والأرض، وتنذر قريشاً صاعقةً مثل صاعقة عاد وثمود، وتخبر بشهادة الجلود على أصحابها، وتعلّم دفع السيئة بالتي هي أحسن فإذا العدو وليٌّ حميم.',
    ],
    42 => [
        'meaning_en' => "Ash-Shura (The Consultation): named after the believers' quality of conducting their affairs by mutual consultation (verse 38).",
        'summary_en' => 'Affirms that Allah legislated for this nation what He enjoined upon Nuh, Ibrahim, Musa and Isa — to establish religion and not divide in it — praises consultation, and explains the three modes by which Allah speaks to humans.',
        'meaning_ar' => 'سُمِّيت بصفة المؤمنين: وأمرهم شورى بينهم (الآية 38).',
        'summary_ar' => 'تقرر أن الله شرع لهذه الأمة ما وصى به نوحاً وإبراهيم وموسى وعيسى: أن أقيموا الدين ولا تتفرقوا فيه، وتمدح الشورى، وتبين طرق تكليم الله للبشر الثلاث.',
    ],
    43 => [
        'meaning_en' => 'Az-Zukhruf (The Gold Adornments): named after the gold ornaments mentioned as mere fleeting enjoyment of worldly life (verses 33-35).',
        'summary_en' => "Refutes the pagans' attribution of daughters to Allah and their plea that the Quran should have descended on a great man of the two cities, declaring that worldly splendor — even roofs of silver and gold — weighs nothing beside the Hereafter.",
        'meaning_ar' => 'سُمِّيت بالزخرف المذكور في بيان حقارة متاع الدنيا (الآيات 33-35).',
        'summary_ar' => 'تبطل نسبة المشركين البنات لله واعتراضهم: لولا نُزِّل هذا القرآن على رجل من القريتين عظيم، وتقرر أن زينة الدنيا — ولو سقفاً من فضة وزخرفاً — لا تزن شيئاً أمام الآخرة.',
    ],
    44 => [
        'meaning_en' => 'Ad-Dukhan (The Smoke): named after the visible smoke that will envelop people as a painful punishment (verses 10-11).',
        'summary_en' => "Opens with the blessed night in which the Quran was sent down, warns of the day the sky brings evident smoke, recounts the drowning of Pharaoh's people who left behind gardens and springs, and contrasts the tree of Zaqqum with the security of the righteous.",
        'meaning_ar' => 'سُمِّيت بالدخان المبين الذي يغشى الناس عذاباً أليماً (الآيتان 10-11).',
        'summary_ar' => 'تفتتح بالليلة المباركة التي أُنزل فيها القرآن، وتنذر يوم تأتي السماء بدخان مبين، وتقص إغراق آل فرعون الذين تركوا جنات وعيون، وتقابل شجرة الزقوم بمقام المتقين الأمين.',
    ],
    45 => [
        'meaning_en' => 'Al-Jathiyah (The Kneeling): named after the scene of every nation kneeling on the Day of Judgment, summoned to its record (verse 28).',
        'summary_en' => 'Marshals the signs of Allah in the heavens, the earth and the alternation of night and day, condemns the one who takes his desire as his god, and depicts every nation on its knees before its book of deeds.',
        'meaning_ar' => 'سُمِّيت بمشهد كل أمة جاثية تُدعى إلى كتابها يوم القيامة (الآية 28).',
        'summary_ar' => 'تحشد آيات الله في السماوات والأرض واختلاف الليل والنهار، وتذم من اتخذ إلهه هواه، وتصور كل أمة جاثية على الركب أمام كتاب أعمالها.',
    ],
    46 => [
        'meaning_en' => "Al-Ahqaf (The Sand Dunes): named after the curved sand dunes, homeland of the people of 'Ad in southern Arabia (verse 21).",
        'summary_en' => "The last of the Ha-Mim surahs: it commands kindness to parents with the prayer of the grateful forty-year-old, recounts Hud's warning to 'Ad at the dunes, and the group of jinn who heard the Quran and returned to their people as warners.",
        'meaning_ar' => 'سُمِّيت بالأحقاف، ديار قوم عاد من الكثبان الرملية جنوب الجزيرة (الآية 21).',
        'summary_ar' => 'آخر سور الحواميم: توصي بالوالدين إحساناً مع دعاء ابن الأربعين الشاكر، وتقص إنذار هود لعاد بالأحقاف، والنفر من الجن الذين استمعوا القرآن فولوا إلى قومهم منذرين.',
    ],
    47 => [
        'meaning_en' => 'Muhammad: named after the Prophet Muhammad, mentioned in its second verse; also called al-Qital (the Fighting).',
        'summary_en' => "Sets the rules of engagement with those who disbelieved and barred from Allah's way, contrasts the rivers of Paradise with the fate of those who followed falsehood, and challenges hearts: will they not reflect on the Quran, or are there locks upon them?",
        'meaning_ar' => 'سُمِّيت باسم النبي محمد ﷺ المذكور في آيتها الثانية، وتسمى أيضاً سورة القتال.',
        'summary_ar' => 'تضع أحكام قتال الذين كفروا وصدوا عن سبيل الله، وتقابل أنهار الجنة بمصير متبعي الباطل، وتقرع القلوب: أفلا يتدبرون القرآن أم على قلوب أقفالها؟',
    ],
    48 => [
        'meaning_en' => 'Al-Fath (The Victory): named after the manifest victory — the Treaty of Hudaybiyyah and what it opened.',
        'summary_en' => "Revealed on the return from Hudaybiyyah; it declares the treaty a manifest victory, records the pledge of Ridwan under the tree, promises the conquest of Mecca and abundant spoils, and closes describing the Prophet's companions in the Torah and the Gospel.",
        'meaning_ar' => 'سُمِّيت بالفتح المبين: صلح الحديبية وما فتحه الله به.',
        'summary_ar' => 'نزلت مرجعَ النبي ﷺ من الحديبية؛ تعلن الصلح فتحاً مبيناً، وتسجل بيعة الرضوان تحت الشجرة، وتعد بفتح مكة ومغانم كثيرة، وتختم بوصف الصحابة في التوراة والإنجيل.',
    ],
    49 => [
        'meaning_en' => "Al-Hujurat (The Chambers): named after the chambers of the Prophet's wives, behind which the Bedouins called out to him (verse 4).",
        'summary_en' => 'The surah of manners: it teaches etiquette with the Prophet, verifying news brought by the corrupt, reconciling believers, and forbids mockery, suspicion, spying and backbiting, declaring the most noble to be the most God-fearing.',
        'meaning_ar' => 'سُمِّيت بحجرات أزواج النبي ﷺ التي ناداه الأعراب من ورائها (الآية 4).',
        'summary_ar' => 'سورة الآداب: تعلّم الأدب مع النبي ﷺ، والتبيُّن من خبر الفاسق، والإصلاح بين المؤمنين، وتحرم السخرية وسوء الظن والتجسس والغيبة، وتقرر أن أكرم الناس أتقاهم.',
    ],
    50 => [
        'meaning_en' => 'Qaf: named after the disconnected letter that opens it.',
        'summary_en' => "Answers astonishment at resurrection after death by pointing to the sky, the earth and the revived dead land; it reminds that two angels record every word, and that the Hour's cry will be heard in truth.",
        'meaning_ar' => 'سُمِّيت بالحرف المقطّع في أولها (ق).',
        'summary_ar' => 'ترد على استبعاد البعث بعد الموت بآيات السماء والأرض وإحياء البلدة الميتة؛ وتذكّر بأن عن اليمين وعن الشمال قعيداً ما يلفظ من قول إلا لديه رقيب عتيد.',
    ],
    51 => [
        'meaning_en' => 'Adh-Dhariyat (The Scattering Winds): named after the winds that scatter, by which the surah opens with an oath.',
        'summary_en' => "Swears by the winds and clouds that the promise of judgment is true, recounts Ibrahim's honored guests and the fates of the people of Lut, Pharaoh, 'Ad and Thamud, and proclaims that jinn and mankind were created only to worship Allah.",
        'meaning_ar' => 'سُمِّيت بالرياح الذاريات التي افتتحت السورة بالقسم بها.',
        'summary_ar' => 'تقسم بالرياح والسحب أن الوعد بالجزاء صادق، وتقص ضيف إبراهيم المكرمين ومصارع قوم لوط وفرعون وعاد وثمود، وتعلن: وما خلقت الجن والإنس إلا ليعبدون.',
    ],
    52 => [
        'meaning_en' => 'At-Tur (The Mount): named after Mount Tur where Allah spoke to Musa, by which the surah opens with an oath.',
        'summary_en' => 'Swears by the Mount and the Inscribed Book that the punishment will surely fall, depicts the bliss of the righteous reunited with their offspring, and pummels the deniers with cascading questions: were they created from nothing, or are they the creators?',
        'meaning_ar' => 'سُمِّيت بجبل الطور الذي كلّم الله عنده موسى، وقد افتتحت بالقسم به.',
        'summary_ar' => 'تقسم بالطور والكتاب المسطور أن عذاب ربك لواقع، وتصور نعيم المتقين وقد أُلحقت بهم ذرياتهم، وتمطر المكذبين بأسئلة متتابعة: أم خُلقوا من غير شيء أم هم الخالقون؟',
    ],
    53 => [
        'meaning_en' => 'An-Najm (The Star): named after the star by which the surah opens with an oath.',
        'summary_en' => "Affirms the truth of the Prophet's vision at the highest horizon and at the Lote Tree of the utmost boundary, demolishes the pagans' goddesses al-Lat, al-'Uzza and Manat, and declares that no soul bears the burden of another and man has only what he strives for.",
        'meaning_ar' => 'سُمِّيت بالنجم الذي افتتحت السورة بالقسم به.',
        'summary_ar' => 'تقرر صدق رؤية النبي ﷺ بالأفق الأعلى وعند سدرة المنتهى، وتهدم أصنام اللات والعزى ومناة، وتعلن ألا تزر وازرة وزر أخرى وأن ليس للإنسان إلا ما سعى.',
    ],
    54 => [
        'meaning_en' => 'Al-Qamar (The Moon): named after the splitting of the moon, the sign granted to the Prophet (verse 1).',
        'summary_en' => "Opens with the split moon and the nearing Hour, then strikes the deniers with the fates of the people of Nuh, 'Ad, Thamud, Lut and Pharaoh — each account sealed with the refrain: and We have certainly made the Quran easy for remembrance.",
        'meaning_ar' => 'سُمِّيت بانشقاق القمر، الآية التي أُعطيها النبي ﷺ (الآية 1).',
        'summary_ar' => 'تفتتح بانشقاق القمر واقتراب الساعة، ثم تضرب المكذبين بمصارع قوم نوح وعاد وثمود وقوم لوط وآل فرعون — وتختم كل قصة باللازمة: ولقد يسرنا القرآن للذكر فهل من مدّكر.',
    ],
    55 => [
        'meaning_en' => "Ar-Rahman (The Most Merciful): named after Allah's name the Most Merciful, with which it opens.",
        'summary_en' => "Called the bride of the Quran: it parades the favors of the Most Merciful upon jinn and mankind — the taught Quran, the sun and moon, the two seas, pearls and coral, the gardens of Paradise — punctuated by the refrain: so which of your Lord's favors will you both deny?",
        'meaning_ar' => 'سُمِّيت باسم الله الرحمن الذي افتتحت به.',
        'summary_ar' => 'تسمى عروس القرآن: تستعرض آلاء الرحمن على الجن والإنس — تعليم القرآن، والشمس والقمر، والبحرين، واللؤلؤ والمرجان، وجنات النعيم — تتخللها اللازمة: فبأي آلاء ربكما تكذبان.',
    ],
    56 => [
        'meaning_en' => "Al-Waqi'ah (The Inevitable Event): named after the Resurrection, the event that will inevitably occur.",
        'summary_en' => 'Divides humanity on that Day into three classes — the foremost brought near, the companions of the right, and the companions of the left — describing the reward and fate of each, and swears by the positions of the stars on the nobility of the Quran.',
        'meaning_ar' => 'سُمِّيت بالواقعة، وهي القيامة التي لا بد أن تقع.',
        'summary_ar' => 'تقسم الناس يومئذ أزواجاً ثلاثة: السابقين المقربين، وأصحاب اليمين، وأصحاب الشمال، وتصف جزاء كل فريق ومآله، وتقسم بمواقع النجوم على كرم القرآن.',
    ],
    57 => [
        'meaning_en' => 'Al-Hadid (The Iron): named after iron, sent down with great might and benefits for mankind (verse 25).',
        'summary_en' => 'Combines glorification of Allah with the call to spend in His way: He who knows what penetrates the earth and what ascends to heaven, who sent messengers with the Book and the balance and sent down iron, warns that worldly life is but play and delusion.',
        'meaning_ar' => 'سُمِّيت بالحديد الذي أنزله الله وفيه بأس شديد ومنافع للناس (الآية 25).',
        'summary_ar' => 'تجمع بين تسبيح الله والحث على الإنفاق في سبيله: فهو العالم بما يلج في الأرض وما يعرج في السماء، أرسل الرسل بالكتاب والميزان وأنزل الحديد، وتحذر أن الحياة الدنيا لعب ولهو وغرور.',
    ],
    58 => [
        'meaning_en' => "Al-Mujadilah (The Pleading Woman): named after the woman who pleaded with the Prophet concerning her husband's zihar oath, and Allah heard her from above the seven heavens.",
        'summary_en' => 'Abolishes the pagan zihar divorce with expiation, declares that no secret counsel of three exists but He is their fourth, regulates private conversation against sin and enmity, and proclaims that the party of Allah are the successful.',
        'meaning_ar' => 'سُمِّيت بالمرأة التي جادلت النبي ﷺ في ظهار زوجها فسمع الله قولها من فوق سبع سماوات.',
        'summary_ar' => 'تبطل ظهار الجاهلية وتوجب كفارته، وتقرر أنه ما يكون من نجوى ثلاثة إلا هو رابعهم، وتنظم التناجي بعيداً عن الإثم والعدوان، وتعلن أن حزب الله هم المفلحون.',
    ],
    59 => [
        'meaning_en' => 'Al-Hashr (The Gathering): named after the banishment and gathering of Banu an-Nadir out of their fortresses.',
        'summary_en' => "Recounts the expulsion of Banu an-Nadir who thought their fortresses would protect them, sets the rules for distributing fay' wealth, praises the Ansar's selflessness, and closes with the most majestic litany of Allah's beautiful names.",
        'meaning_ar' => 'سُمِّيت بحشر بني النضير وإجلائهم من حصونهم.',
        'summary_ar' => 'تقص إجلاء بني النضير الذين ظنوا أن حصونهم مانعتهم من الله، وتضع أحكام قسمة الفيء، وتثني على إيثار الأنصار، وتختم بأجلّ سرد لأسماء الله الحسنى.',
    ],
    60 => [
        'meaning_en' => 'Al-Mumtahanah (The Woman Examined): named after the command to examine the believing women who emigrated (verse 10).',
        'summary_en' => "Forbids taking Allah's enemies as allies after the incident of Hatib's letter, presents Ibrahim as the model of disavowal from idolatry, permits kindness to peaceable non-believers, and legislates the examination and pledge of emigrant believing women.",
        'meaning_ar' => 'سُمِّيت بامتحان المؤمنات المهاجرات (الآية 10).',
        'summary_ar' => 'تنهى عن موالاة أعداء الله بعد حادثة كتاب حاطب، وتقدم إبراهيم أسوة في البراءة من الشرك، وتبيح البر بالمسالمين من غير المؤمنين، وتشرع امتحان المهاجرات ومبايعتهن.',
    ],
    61 => [
        'meaning_en' => "As-Saff (The Ranks): named after Allah's love for those who fight in His cause in ranks as if a solid structure (verse 4).",
        'summary_en' => "Rebukes saying what one does not do, recalls Isa's glad tidings of a messenger named Ahmad, and calls the believers to a commerce that saves from painful punishment: faith and striving in Allah's way, with the promise of near victory.",
        'meaning_ar' => 'سُمِّيت بحب الله للذين يقاتلون في سبيله صفاً كأنهم بنيان مرصوص (الآية 4).',
        'summary_ar' => 'تعاتب من يقولون ما لا يفعلون، وتذكر بشارة عيسى برسول اسمه أحمد، وتدعو المؤمنين إلى تجارة تنجي من عذاب أليم: الإيمان والجهاد في سبيل الله، مع وعد بنصر قريب وفتح.',
    ],
    62 => [
        'meaning_en' => "Al-Jumu'ah (Friday): named after the congregational Friday prayer it ordains.",
        'summary_en' => "Declares the Prophet's mission to an unlettered people to recite, purify and teach, likens those who were given the Torah but did not carry it to a donkey carrying volumes, and commands hastening to the remembrance of Allah when the Friday call is made.",
        'meaning_ar' => 'سُمِّيت بصلاة الجمعة التي فرضتها.',
        'summary_ar' => 'تعلن بعثة النبي ﷺ في الأميين يتلو ويزكي ويعلّم، وتشبّه الذين حُمِّلوا التوراة ثم لم يحملوها بالحمار يحمل أسفاراً، وتأمر بالسعي إلى ذكر الله إذا نودي لصلاة الجمعة.',
    ],
    63 => [
        'meaning_en' => 'Al-Munafiqun (The Hypocrites): named after its exposure of the hypocrites and their ringleader Abdullah ibn Ubayy.',
        'summary_en' => "Unmasks the hypocrites whose oaths are shields and whose appearance deceives — like propped-up timbers — records their threat to expel the weaker from Medina, and warns believers against being distracted by wealth and children from Allah's remembrance.",
        'meaning_ar' => 'سُمِّيت بفضحها للمنافقين وزعيمهم عبد الله بن أُبيّ.',
        'summary_ar' => 'تكشف المنافقين الذين اتخذوا أيمانهم جُنة وتعجبك أجسامهم كأنهم خشب مسندة، وتسجل قولهم: ليُخرجن الأعز منها الأذل، وتحذر المؤمنين أن تلهيهم أموالهم وأولادهم عن ذكر الله.',
    ],
    64 => [
        'meaning_en' => 'At-Taghabun (The Mutual Disillusion): named after the Day of Judgment as the day of mutual loss and gain (verse 9).',
        'summary_en' => "Proclaims that all in the heavens and earth glorifies Allah who created and shaped mankind, affirms that no calamity strikes except by Allah's permission, and warns that among spouses and children are enemies — yet pardon and forgiveness are better.",
        'meaning_ar' => 'سُمِّيت بيوم التغابن، يوم القيامة حيث يغبن أهل الجنة أهل النار (الآية 9).',
        'summary_ar' => 'تعلن تسبيح ما في السماوات والأرض لله الذي خلق فأحسن الصور، وتقرر أن ما أصاب من مصيبة إلا بإذن الله، وتنبه أن من الأزواج والأولاد عدواً — وأن العفو والصفح أقرب للتقوى.',
    ],
    65 => [
        'meaning_en' => 'At-Talaq (The Divorce): named after its detailed rulings on divorce and the waiting period.',
        'summary_en' => 'Legislates divorce with its proper timing, the counting of waiting periods, housing and maintenance for divorced women, and the provision for nursing mothers — interlaced with the promise that whoever fears Allah, He will make a way out for him.',
        'meaning_ar' => 'سُمِّيت بأحكام الطلاق والعدة التي فصّلتها.',
        'summary_ar' => 'تشرع الطلاق في وقته، وإحصاء العدة، وسكنى المطلقات ونفقتهن، وأجر المرضعات — ويتخللها الوعد: ومن يتق الله يجعل له مخرجاً ويرزقه من حيث لا يحتسب.',
    ],
    66 => [
        'meaning_en' => "At-Tahrim (The Prohibition): named after the Prophet's prohibiting upon himself what Allah had made lawful, seeking his wives' pleasure (verse 1).",
        'summary_en' => "Addresses an episode in the Prophet's household and the duty of guarding oneself and one's family from the Fire, then closes with four exemplary women: the wives of Nuh and Lut as warnings, and Pharaoh's wife and Maryam as models of faith.",
        'meaning_ar' => 'سُمِّيت بتحريم النبي ﷺ على نفسه ما أحل الله ابتغاء مرضاة أزواجه (الآية 1).',
        'summary_ar' => 'تعالج حادثة في بيت النبوة وواجب وقاية النفس والأهل ناراً وقودها الناس والحجارة، وتختم بأربع نساء: امرأتي نوح ولوط عبرةً، وامرأة فرعون ومريم مثلاً للإيمان.',
    ],
    67 => [
        'meaning_en' => 'Al-Mulk (The Sovereignty): named after Allah in whose hand is all dominion; also called Tabarak and al-Munjiyah (the Savior from the punishment of the grave).',
        'summary_en' => 'Glorifies the One who created death and life to test which of you is best in deed, points to the flawless seven heavens and the birds held aloft, and records the regret of the people of the Fire: had we listened or reasoned, we would not be among its companions.',
        'meaning_ar' => 'سُمِّيت بالملك الذي بيد الله، وتسمى تبارك والمُنجية من عذاب القبر.',
        'summary_ar' => 'تمجّد الذي خلق الموت والحياة ليبلوكم أيكم أحسن عملاً، وتشير إلى السماوات السبع بلا تفاوت والطير صافات، وتسجل حسرة أهل النار: لو كنا نسمع أو نعقل ما كنا في أصحاب السعير.',
    ],
    68 => [
        'meaning_en' => 'Al-Qalam (The Pen): named after the pen by which the surah opens with an oath; also called Nun.',
        'summary_en' => 'Defends the Prophet against the charge of madness, declaring him upon a great standard of character, tells the story of the owners of the garden who resolved to deprive the poor and woke to find it razed, and commands patience like that demanded of Yunus.',
        'meaning_ar' => 'سُمِّيت بالقلم الذي افتتحت السورة بالقسم به، وتسمى أيضاً سورة نون.',
        'summary_ar' => 'تدافع عن النبي ﷺ ضد تهمة الجنون وتعلن أنه على خلق عظيم، وتقص أصحاب الجنة الذين بيّتوا حرمان المساكين فأصبحت كالصريم، وتأمر بالصبر وألا يكون كصاحب الحوت.',
    ],
    69 => [
        'meaning_en' => 'Al-Haqqah (The Inevitable Reality): named after the Resurrection, the reality that will surely come to pass.',
        'summary_en' => "Recalls how Thamud, 'Ad and Pharaoh denied the striking calamity and were seized, depicts the trumpet blast, the split sky and the presented souls — the one given his book in his right hand rejoicing, the other wishing he had never known his account.",
        'meaning_ar' => 'سُمِّيت بالحاقة، وهي القيامة التي تحق ولا بد واقعة.',
        'summary_ar' => 'تذكّر بتكذيب ثمود وعاد وفرعون بالقارعة وكيف أُخذوا، وتصور النفخة وانشقاق السماء والعرض: فآخذ كتابه بيمينه فرحاً، وآخذه بشماله يتمنى أنه لم يدرِ ما حسابه.',
    ],
    70 => [
        'meaning_en' => "Al-Ma'arij (The Ascending Ways): named after Allah, Lord of the ways of ascent by which the angels rise to Him.",
        'summary_en' => "Answers a scoffer's demand for the punishment to fall, on a Day whose measure is fifty thousand years, when no friend asks about a friend, and diagnoses man as anxious and withholding — except the praying ones who keep their prayer and acknowledge the rights of the needy.",
        'meaning_ar' => 'سُمِّيت بالمعارج التي تعرج بها الملائكة والروح إلى الله.',
        'summary_ar' => 'ترد على سائل سأل بعذاب واقع، في يوم مقداره خمسون ألف سنة لا يسأل حميم حميماً، وتشخّص الإنسان هلوعاً جزوعاً منوعاً — إلا المصلين الدائمين على صلاتهم وفي أموالهم حق للسائل والمحروم.',
    ],
    71 => [
        'meaning_en' => 'Nuh (Noah): named after Prophet Nuh, whose mission it recounts from beginning to end.',
        'summary_en' => "Devoted entirely to Nuh's nine hundred and fifty years of calling: openly and secretly, with promises of rains, wealth and gardens for seeking forgiveness, until his final prayer when nothing remained but to wash the earth of the obstinate idolaters.",
        'meaning_ar' => 'سُمِّيت بنبي الله نوح، وقد خُصّت بقصة دعوته كاملة.',
        'summary_ar' => 'خالصة لقصة نوح وألف سنة إلا خمسين عاماً من الدعوة: جهراً وإسراراً، بوعد الغيث والأموال والجنات لمن استغفر، حتى دعائه الأخير حين لم يبقَ إلا تطهير الأرض من عتاة الشرك.',
    ],
    72 => [
        'meaning_en' => 'Al-Jinn (The Jinn): named after the group of jinn who listened to the Quran and believed.',
        'summary_en' => 'Reports the words of the jinn who heard an amazing recitation and declared they would never associate anyone with their Lord, corrects superstitions about seeking refuge with jinn, and affirms that the unseen belongs to Allah alone, revealed only to approved messengers.',
        'meaning_ar' => 'سُمِّيت بالنفر من الجن الذين استمعوا القرآن فآمنوا.',
        'summary_ar' => 'تحكي قول الجن الذين سمعوا قرآناً عجباً فقالوا: ولن نشرك بربنا أحداً، وتصحح خرافة الاستعاذة برجال الجن، وتقرر أن الغيب لله وحده لا يُظهر عليه إلا من ارتضى من رسول.',
    ],
    73 => [
        'meaning_en' => 'Al-Muzzammil (The Enwrapped One): named after the address to the Prophet wrapped in his garments.',
        'summary_en' => "Commands the wrapped Prophet to stand in night prayer and recite the Quran with measured recitation, to bear the weighty word with beautiful patience, and ends easing the night vigil for him and the believers alongside prayer, charity and seeking Allah's bounty.",
        'meaning_ar' => 'سُمِّيت بنداء النبي ﷺ المتزمل بثيابه.',
        'summary_ar' => 'تأمر النبي المتزمل بقيام الليل وترتيل القرآن ترتيلاً، وحمل القول الثقيل بالصبر الجميل، وتختم بالتخفيف في القيام عليه وعلى المؤمنين مع الصلاة والزكاة والضرب في الأرض.',
    ],
    74 => [
        'meaning_en' => 'Al-Muddaththir (The Cloaked One): named after the address to the Prophet cloaked in his garments — among the first revelations commanding him to arise and warn.',
        'summary_en' => 'Commissions the Prophet: arise and warn, and magnify your Lord; it recounts the obstinate denier who schemed against the Quran, describes Saqar which spares nothing, and declares every soul held in pledge for its deeds except the companions of the right.',
        'meaning_ar' => 'سُمِّيت بنداء النبي ﷺ المدثر بثيابه، وهي من أوائل ما نزل بأمر الإنذار.',
        'summary_ar' => 'تكلف النبي ﷺ: قم فأنذر وربك فكبّر؛ وتقص العنيد الذي قدّر وكاد للقرآن، وتصف سقر لا تبقي ولا تذر، وتقرر أن كل نفس بما كسبت رهينة إلا أصحاب اليمين.',
    ],
    75 => [
        'meaning_en' => 'Al-Qiyamah (The Resurrection): named after the Day of Resurrection by which it opens with an oath.',
        'summary_en' => "Swears by the Day of Resurrection and the self-reproaching soul that Allah will reassemble man's very fingertips, instructs the Prophet not to hasten his tongue with the revelation, and contrasts radiant faces gazing at their Lord with faces darkened by despair.",
        'meaning_ar' => 'سُمِّيت بيوم القيامة الذي افتتحت بالقسم به.',
        'summary_ar' => 'تقسم بيوم القيامة والنفس اللوامة على أن الله قادر أن يسوي بنان الإنسان، وتوجه النبي ألا يحرك لسانه ليعجل بالوحي، وتقابل وجوهاً ناضرة إلى ربها ناظرة بوجوه باسرة.',
    ],
    76 => [
        'meaning_en' => "Al-Insan (Man): named after its opening question about man's coming to be; also called ad-Dahr (Time).",
        'summary_en' => 'Traces man from a drop tested with hearing and sight to the choice of gratitude or denial, and lavishes its verses on the righteous who feed the needy, orphan and captive for the love of Allah, seeking neither reward nor thanks.',
        'meaning_ar' => 'سُمِّيت بالإنسان لافتتاحها بالسؤال عن نشأته، وتسمى أيضاً سورة الدهر.',
        'summary_ar' => 'تتتبع الإنسان من نطفة أمشاج مبتلى بالسمع والبصر إلى اختيار الشكر أو الكفور، وتفيض في وصف الأبرار الذين يطعمون الطعام على حبه مسكيناً ويتيماً وأسيراً لا يريدون جزاءً ولا شكوراً.',
    ],
    77 => [
        'meaning_en' => 'Al-Mursalat (The Emissaries): named after the winds sent forth in succession, by which it opens with an oath.',
        'summary_en' => "Swears by the sent winds that what is promised will occur, then hammers its warning through ten refrains of 'woe that Day to the deniers', marshaling proofs from creation, the earth that gathers the living and the dead, and the fates of earlier nations.",
        'meaning_ar' => 'سُمِّيت بالرياح المرسلات عرفاً التي افتتحت بالقسم بها.',
        'summary_ar' => 'تقسم بالمرسلات أن ما توعدون لواقع، ثم تقرع بالإنذار عبر لازمة تكررت عشر مرات: ويل يومئذ للمكذبين، محتشدة بأدلة الخلق والأرض الكفات والأمم الغابرة.',
    ],
    78 => [
        'meaning_en' => 'An-Naba (The Tidings): named after the great tidings of resurrection about which the people dispute.',
        'summary_en' => 'Answers those questioning the great news with proofs: the earth a cradle, the mountains pegs, sleep for rest and the day for livelihood — then depicts the Day of Sorting, Hell lying in wait, and the gardens of the righteous.',
        'meaning_ar' => 'سُمِّيت بالنبأ العظيم الذي يتساءلون عنه، وهو البعث.',
        'summary_ar' => 'تجيب المتسائلين عن النبأ العظيم بالأدلة: الأرض مهاداً والجبال أوتاداً والنوم سباتاً والنهار معاشاً — ثم تصور يوم الفصل وجهنم المرصاد وحدائق المتقين.',
    ],
    79 => [
        'meaning_en' => "An-Nazi'at (The Extractors): named after the angels who wrest out the souls, by which it opens with an oath.",
        'summary_en' => "Swears by the angels of death that the quaking blast will come, recounts Musa's confrontation with Pharaoh who claimed lordship and was seized, and asks whether mankind is harder to create than the heaven Allah built.",
        'meaning_ar' => 'سُمِّيت بالملائكة النازعات للأرواح التي افتتحت بالقسم بها.',
        'summary_ar' => 'تقسم بملائكة قبض الأرواح على مجيء الراجفة، وتقص مواجهة موسى لفرعون الذي ادعى الربوبية فأخذه الله نكال الآخرة والأولى، وتسأل: أأنتم أشد خلقاً أم السماء بناها؟',
    ],
    80 => [
        'meaning_en' => "'Abasa (He Frowned): named after the gentle correction of the Prophet when he frowned at the blind man Ibn Umm Maktum who came seeking knowledge.",
        'summary_en' => "Establishes that the measure of people is their faith, not their standing: the blind seeker deserves welcome over the self-sufficient notable; it then turns to man's ingratitude despite the provision of his food, and the Day each person flees from his own kin.",
        'meaning_ar' => 'سُمِّيت بعتاب النبي ﷺ حين عبس للأعمى ابن أم مكتوم وقد جاء يسعى للعلم.',
        'summary_ar' => 'تقرر أن ميزان الناس إيمانهم لا جاههم: فالأعمى الساعي للذكرى أولى ممن استغنى؛ ثم تنتقل إلى كفر الإنسان بالنعمة رغم تيسير طعامه، ويوم يفر المرء من أخيه وأمه وأبيه.',
    ],
    81 => [
        'meaning_en' => 'At-Takwir (The Folding Up): named after the folding up of the sun at the end of the world.',
        'summary_en' => 'Paints the cosmic upheaval of the Hour in twelve scenes — the sun folded, the stars scattered, the buried girl asked for what sin she was killed — then vindicates the revelation brought by a noble, trustworthy messenger-angel.',
        'meaning_ar' => 'سُمِّيت بتكوير الشمس عند خراب العالم.',
        'summary_ar' => 'ترسم انقلاب الكون يوم الساعة في اثني عشر مشهداً: الشمس كُوِّرت، والنجوم انكدرت، والموءودة سُئلت بأي ذنب قُتلت — ثم تثبت أن القرآن قول رسول كريم أمين.',
    ],
    82 => [
        'meaning_en' => 'Al-Infitar (The Splitting): named after the splitting of the sky on the Last Day.',
        'summary_en' => 'Depicts the sky split, the stars dispersed and the graves overturned, then reproaches man: what deceived you about your Generous Lord who shaped you in whatever form He willed — while noble recording angels know whatever you do?',
        'meaning_ar' => 'سُمِّيت بانفطار السماء يوم القيامة.',
        'summary_ar' => 'تصور السماء منفطرة والكواكب منتثرة والقبور مبعثرة، ثم تعاتب الإنسان: ما غرّك بربك الكريم الذي خلقك فسواك فعدلك — وإن عليكم لحافظين كراماً كاتبين.',
    ],
    83 => [
        'meaning_en' => 'Al-Mutaffifin (The Defrauders): named after those who give short measure and weight.',
        'summary_en' => "Threatens woe upon those who demand full measure for themselves but cheat others, declares the records of the wicked in Sijjin and of the righteous in 'Illiyyun, and promises that today the believers will laugh at those who once mocked them.",
        'meaning_ar' => 'سُمِّيت بالمطففين الذين يبخسون الكيل والميزان.',
        'summary_ar' => 'تتوعد بالويل الذين يستوفون لأنفسهم ويُخسرون غيرهم، وتقرر أن كتاب الفجار في سجين وكتاب الأبرار في عليين، وتعد بأن اليومَ الذين آمنوا من الكفار يضحكون.',
    ],
    84 => [
        'meaning_en' => 'Al-Inshiqaq (The Sundering): named after the rending of the sky in obedience to its Lord.',
        'summary_en' => "Shows the sky and earth surrendering to their Lord's command, declares that man is laboring toward his Lord and will meet Him, and contrasts the easy reckoning of the one given his book in his right hand with the cry of the one given it behind his back.",
        'meaning_ar' => 'سُمِّيت بانشقاق السماء طاعةً لربها.',
        'summary_ar' => 'تعرض السماء والأرض وقد أذنتا لربهما وحُقت لهما، وتقرر أن الإنسان كادح إلى ربه كدحاً فملاقيه، وتقابل الحساب اليسير لآخذ كتابه بيمينه بثبور من أوتيه وراء ظهره.',
    ],
    85 => [
        'meaning_en' => 'Al-Buruj (The Constellations): named after the sky holding the great constellations, by which it opens with an oath.',
        'summary_en' => "Tells of the people of the trench who burned the believers alive for nothing except faith in the Almighty, promises the persecutors Hell and the believers gardens, and reminds tyrants of the fate of Pharaoh's hosts and Thamud.",
        'meaning_ar' => 'سُمِّيت بالسماء ذات البروج التي افتتحت بالقسم بها.',
        'summary_ar' => 'تقص أصحاب الأخدود الذين أحرقوا المؤمنين أحياءً وما نقموا منهم إلا أن يؤمنوا بالله العزيز الحميد، وتعد المعذِّبين بجهنم والمؤمنين بالجنات، وتذكّر الطغاة بجنود فرعون وثمود.',
    ],
    86 => [
        'meaning_en' => 'At-Tariq (The Night Visitor): named after the piercing star that comes by night, by which it opens with an oath.',
        'summary_en' => "Swears by the piercing night star that every soul has a watchful keeper, invites man to consider the gushing water from which he was created as proof that his return is well within Allah's power, and describes the Quran as a decisive word, no jest.",
        'meaning_ar' => 'سُمِّيت بالطارق، النجم الثاقب الذي افتتحت بالقسم به.',
        'summary_ar' => 'تقسم بالنجم الثاقب أن كل نفس عليها حافظ، وتدعو الإنسان للنظر مم خُلق — من ماء دافق — دليلاً على القدرة على رجعه، وتصف القرآن بأنه قول فصل وما هو بالهزل.',
    ],
    87 => [
        'meaning_en' => "Al-A'la (The Most High): named after the command to glorify the name of your Lord, the Most High.",
        'summary_en' => 'Commands glorifying the Lord who created, proportioned and guided, reassures the Prophet that he will be made to recite and not forget, and declares that success belongs to whoever purifies himself — a truth found in the earlier scrolls of Ibrahim and Musa.',
        'meaning_ar' => 'سُمِّيت بالأمر بتسبيح اسم الرب الأعلى.',
        'summary_ar' => 'تأمر بتسبيح الرب الذي خلق فسوى وقدّر فهدى، وتطمئن النبي ﷺ: سنقرئك فلا تنسى، وتقرر أن قد أفلح من تزكى — وأن ذلك في الصحف الأولى صحف إبراهيم وموسى.',
    ],
    88 => [
        'meaning_en' => 'Al-Ghashiyah (The Overwhelming): named after the Resurrection that overwhelms all with its terrors.',
        'summary_en' => 'Contrasts faces that Day humbled, toiling and scorched, with faces joyful in a lofty garden, then directs attention to the camel, the sky, the mountains and the earth as proofs, reminding the Prophet that he is only a reminder, not a controller over them.',
        'meaning_ar' => 'سُمِّيت بالغاشية التي تغشى الناس بأهوالها يوم القيامة.',
        'summary_ar' => 'تقابل وجوهاً يومئذ خاشعة عاملة ناصبة بوجوه ناعمة في جنة عالية، ثم توجه النظر إلى الإبل والسماء والجبال والأرض دليلاً، وتذكّر النبي: إنما أنت مذكر لست عليهم بمسيطر.',
    ],
    89 => [
        'meaning_en' => 'Al-Fajr (The Dawn): named after the dawn by which it opens with an oath.',
        'summary_en' => "Swears by the dawn and ten nights, recalls how 'Ad of the pillars, Thamud and Pharaoh of the stakes transgressed and were poured a scourge of punishment, rebukes the neglect of orphans and the devouring of inheritance, and closes with the serene soul invited into Paradise.",
        'meaning_ar' => 'سُمِّيت بالفجر الذي افتتحت بالقسم به.',
        'summary_ar' => 'تقسم بالفجر وليالٍ عشر، وتذكّر بعاد إرم ذات العماد وثمود وفرعون ذي الأوتاد الذين طغوا فصب عليهم ربك سوط عذاب، وتوبخ إهانة اليتيم وأكل التراث، وتختم بالنفس المطمئنة المدعوة إلى الجنة.',
    ],
    90 => [
        'meaning_en' => 'Al-Balad (The City): named after Mecca, the sacred city by which Allah swears while the Prophet dwells in it.',
        'summary_en' => 'Swears by Mecca that man was created in toil, asks why he has not attempted the steep ascent — freeing a slave, feeding in days of hunger an orphaned relative or a needy person in the dust — and being among those who counsel patience and compassion.',
        'meaning_ar' => 'سُمِّيت بالبلد الحرام مكة التي أقسم الله بها والنبي حِلٌّ بها.',
        'summary_ar' => 'تقسم بمكة أن الإنسان خُلق في كبد، وتسأل: فلا اقتحم العقبة — فك رقبة، أو إطعام في يوم ذي مسغبة يتيماً ذا مقربة أو مسكيناً ذا متربة — ثم الكون من الذين تواصوا بالصبر والمرحمة.',
    ],
    91 => [
        'meaning_en' => 'Ash-Shams (The Sun): named after the sun by which it opens with an oath.',
        'summary_en' => 'Opens with eleven oaths culminating in the soul and Him who fashioned it, inspiring it with its wickedness and its righteousness — he succeeds who purifies it — then cites Thamud, who hamstrung the she-camel and were leveled for their sin.',
        'meaning_ar' => 'سُمِّيت بالشمس التي افتتحت بالقسم بها.',
        'summary_ar' => 'تفتتح بأحد عشر قسماً ختامها النفس وما سواها فألهمها فجورها وتقواها — قد أفلح من زكاها — ثم تستشهد بثمود الذين عقروا الناقة فدمدم عليهم ربهم بذنبهم فسواها.',
    ],
    92 => [
        'meaning_en' => 'Al-Layl (The Night): named after the night by which it opens with an oath.',
        'summary_en' => 'Swears by the night and the day that human striving is diverse: whoever gives, fears Allah and affirms the best, Allah eases him toward ease; whoever is miserly and self-sufficient, toward hardship — and the most God-fearing, who gives his wealth to purify himself, will be kept away from the Fire.',
        'meaning_ar' => 'سُمِّيت بالليل الذي افتتحت بالقسم به.',
        'summary_ar' => 'تقسم بالليل والنهار أن سعي الناس شتى: فمن أعطى واتقى وصدّق بالحسنى فسنيسره لليسرى، ومن بخل واستغنى فسنيسره للعسرى — وسيُجنَّب النارَ الأتقى الذي يؤتي ماله يتزكى.',
    ],
    93 => [
        'meaning_en' => 'Ad-Duha (The Morning Brightness): named after the morning light by which it opens with an oath.',
        'summary_en' => "Revealed when revelation paused and the pagans claimed the Prophet's Lord had forsaken him: it swears that your Lord has not abandoned you nor detests you, recalls His care for the orphan and wanderer, and commands honoring the orphan, the beggar and the favor of your Lord.",
        'meaning_ar' => 'سُمِّيت بالضحى الذي افتتحت بالقسم به.',
        'summary_ar' => 'نزلت حين فتر الوحي وزعم المشركون أن ربه ودّعه: تقسم أن ما ودعك ربك وما قلى، وتذكّر برعايته يتيماً وضالاً وعائلاً، وتأمر: فأما اليتيم فلا تقهر، وأما السائل فلا تنهر، وأما بنعمة ربك فحدث.',
    ],
    94 => [
        'meaning_en' => "Ash-Sharh (The Expansion): named after the opening of the Prophet's breast; also called al-Inshirah.",
        'summary_en' => "Consoles the Prophet by counting Allah's favors — his breast expanded, his burden removed, his mention raised — and plants the enduring promise repeated twice: indeed, with hardship comes ease; so when free, exert yourself and to your Lord turn with longing.",
        'meaning_ar' => 'سُمِّيت بشرح صدر النبي ﷺ، وتسمى أيضاً سورة الانشراح.',
        'summary_ar' => 'تواسي النبي ﷺ بتعداد المنن: شرح صدره، ووضع وزره، ورفع ذكره، وتغرس الوعد المكرر مرتين: فإن مع العسر يسراً، إن مع العسر يسراً — فإذا فرغت فانصب وإلى ربك فارغب.',
    ],
    95 => [
        'meaning_en' => 'At-Tin (The Fig): named after the fig by which it opens with an oath, alongside the olive, Mount Sinai and the secure city.',
        'summary_en' => 'Swears by the lands of revelation that Allah created man in the best of stature, then he may be reduced to the lowest of the low — except those who believe and do righteous deeds — and asks: what then makes you deny the Judgment? Is not Allah the most just of judges?',
        'meaning_ar' => 'سُمِّيت بالتين الذي افتتحت بالقسم به مع الزيتون وطور سينين والبلد الأمين.',
        'summary_ar' => 'تقسم بمواطن الوحي أن الله خلق الإنسان في أحسن تقويم، ثم قد يُرد إلى أسفل سافلين — إلا الذين آمنوا وعملوا الصالحات — وتسأل: فما يكذبك بعد بالدين؟ أليس الله بأحكم الحاكمين؟',
    ],
    96 => [
        'meaning_en' => "Al-'Alaq (The Clinging Clot): named after the clot from which man was created; its opening five verses were the first revelation.",
        'summary_en' => 'Begins with the very first words of revelation in the cave of Hira — Read in the name of your Lord who created — honors the pen and teaching, then warns the tyrant who forbids a servant when he prays: let him beware the seizing of the forelock; prostrate and draw near.',
        'meaning_ar' => 'سُمِّيت بالعلق الذي خُلق منه الإنسان، وآياتها الخمس الأولى أولُ ما نزل من القرآن.',
        'summary_ar' => 'تبدأ بأول كلمات الوحي في غار حراء: اقرأ باسم ربك الذي خلق، وتكرّم القلم والتعليم، ثم تنذر الطاغية الذي ينهى عبداً إذا صلى: ليحذر السفع بالناصية — واسجد واقترب.',
    ],
    97 => [
        'meaning_en' => 'Al-Qadr (The Decree): named after the Night of Decree in which the Quran was sent down.',
        'summary_en' => "Announces the descent of the Quran on the Night of Decree, better than a thousand months, in which the angels and the Spirit descend by their Lord's permission with every matter — peace it is until the rising of dawn.",
        'meaning_ar' => 'سُمِّيت بليلة القدر التي أُنزل فيها القرآن.',
        'summary_ar' => 'تعلن إنزال القرآن في ليلة القدر، خير من ألف شهر، تنزّل الملائكة والروح فيها بإذن ربهم من كل أمر — سلام هي حتى مطلع الفجر.',
    ],
    98 => [
        'meaning_en' => 'Al-Bayyinah (The Clear Evidence): named after the clear proof — the Messenger reciting purified pages.',
        'summary_en' => 'States that the People of the Book and the idolaters would not desist until clear evidence came to them, and that they were commanded only to worship Allah with sincere devotion, establish prayer and give zakah — those who believe and do good are the best of creation.',
        'meaning_ar' => 'سُمِّيت بالبينة، وهي الحجة الواضحة: رسول يتلو صحفاً مطهرة.',
        'summary_ar' => 'تقرر أن أهل الكتاب والمشركين لم يكونوا منفكين حتى تأتيهم البينة، وما أُمروا إلا ليعبدوا الله مخلصين له الدين ويقيموا الصلاة ويؤتوا الزكاة — والذين آمنوا وعملوا الصالحات هم خير البرية.',
    ],
    99 => [
        'meaning_en' => 'Az-Zalzalah (The Earthquake): named after the final earthquake of the earth.',
        'summary_en' => "Depicts the earth convulsed with her final quaking, casting out her burdens and recounting her news because her Lord inspired her — the Day mankind proceeds in scattered groups to be shown their deeds: whoever does an atom's weight of good or evil will see it.",
        'meaning_ar' => 'سُمِّيت بزلزلة الأرض زلزالها الأخير.',
        'summary_ar' => 'تصور الأرض وقد زُلزلت زلزالها وأخرجت أثقالها وحدثت أخبارها بأن ربها أوحى لها — يومئذ يصدر الناس أشتاتاً ليُروا أعمالهم: فمن يعمل مثقال ذرة خيراً يره ومن يعمل مثقال ذرة شراً يره.',
    ],
    100 => [
        'meaning_en' => "Al-'Adiyat (The Charging Steeds): named after the war horses charging with panting breath, by which it opens with an oath.",
        'summary_en' => 'Swears by the charging steeds striking sparks that man is ungrateful to his Lord — himself a witness to it — and intense in love of wealth; does he not know that when the graves are overturned, their Lord that Day is fully acquainted with them?',
        'meaning_ar' => 'سُمِّيت بخيل الغزو العاديات ضبحاً التي افتتحت بالقسم بها.',
        'summary_ar' => 'تقسم بالخيل العاديات الموريات قدحاً أن الإنسان لربه لكنود، وإنه على ذلك لشهيد، وإنه لحب الخير لشديد — أفلا يعلم إذا بُعثر ما في القبور أن ربهم بهم يومئذ لخبير؟',
    ],
    101 => [
        'meaning_en' => "Al-Qari'ah (The Striking Calamity): named after the Resurrection that strikes hearts with its terror.",
        'summary_en' => "Asks what the striking calamity is — the Day people are like scattered moths and mountains like carded wool — then weighs the scales: whoever's weigh heavy is in a pleasant life, and whoever's weigh light, his refuge is an abyss of raging fire.",
        'meaning_ar' => 'سُمِّيت بالقارعة التي تقرع القلوب بأهوالها.',
        'summary_ar' => 'تسأل: ما القارعة؟ يوم يكون الناس كالفراش المبثوث والجبال كالعهن المنفوش — ثم توزن الموازين: فمن ثقلت موازينه فهو في عيشة راضية، ومن خفت فأمه هاوية، نار حامية.',
    ],
    102 => [
        'meaning_en' => 'At-Takathur (The Rivalry in Increase): named after the competition in amassing wealth and children that diverts people.',
        'summary_en' => 'Rebukes the obsession with accumulating more until graves are visited, warns with mounting emphasis that they will surely come to know, promises they will see the Hellfire with the eye of certainty, and that they will be asked that Day about the pleasures they enjoyed.',
        'meaning_ar' => 'سُمِّيت بالتكاثر في الأموال والأولاد الذي يلهي الناس.',
        'summary_ar' => 'توبخ الانشغال بالتكاثر حتى زيارة المقابر، وتنذر بتوكيد متصاعد: كلا سوف تعلمون، وتعد برؤية الجحيم عين اليقين، وبالسؤال يومئذ عن النعيم.',
    ],
    103 => [
        'meaning_en' => "Al-'Asr (The Time): named after the time by which Allah swears.",
        'summary_en' => "Three verses holding a complete scale of salvation: by time, mankind is in loss — except those who believe, do righteous deeds, and counsel one another to truth and to patience. Imam ash-Shafi'i said: had only this surah been revealed, it would have sufficed the people.",
        'meaning_ar' => 'سُمِّيت بالعصر الذي أقسم الله به، وهو الدهر.',
        'summary_ar' => 'ثلاث آيات فيها ميزان النجاة كاملاً: والعصر إن الإنسان لفي خسر — إلا الذين آمنوا وعملوا الصالحات وتواصوا بالحق وتواصوا بالصبر. قال الشافعي: لو ما أنزل الله حجة على خلقه إلا هذه السورة لكفتهم.',
    ],
    104 => [
        'meaning_en' => 'Al-Humazah (The Slanderer): named after the slanderer and backbiter it condemns.',
        'summary_en' => 'Pronounces woe upon every slandering backbiter who amasses wealth and counts it, thinking it will immortalize him — he will surely be thrown into the Crusher, the kindled fire of Allah which mounts up to the hearts.',
        'meaning_ar' => 'سُمِّيت بالهُمَزة، الطعّان المغتاب الذي توعدته.',
        'summary_ar' => 'تتوعد بالويل كل همزة لمزة جمع مالاً وعدده يحسب أن ماله أخلده — لينبذن في الحطمة، نار الله الموقدة التي تطّلع على الأفئدة.',
    ],
    105 => [
        'meaning_en' => "Al-Fil (The Elephant): named after the army of the elephant that marched to destroy the Ka'bah.",
        'summary_en' => "Recalls how Allah dealt with Abrahah's elephant army in the year of the Prophet's birth: He sent against them birds in flocks pelting them with stones of baked clay, leaving them like devoured straw — a standing proof of His protection of His House.",
        'meaning_ar' => 'سُمِّيت بأصحاب الفيل الذين ساروا لهدم الكعبة.',
        'summary_ar' => 'تذكّر بصنيع الله بجيش أبرهة عام مولد النبي ﷺ: أرسل عليهم طيراً أبابيل ترميهم بحجارة من سجيل فجعلهم كعصف مأكول — آيةً باقية على حماية الله لبيته.',
    ],
    106 => [
        'meaning_en' => "Quraysh: named after the tribe of Quraysh, custodians of the Ka'bah.",
        'summary_en' => "Reminds Quraysh of Allah's favor in securing their winter and summer trade journeys, and calls them to worship the Lord of this House who fed them against hunger and made them safe from fear.",
        'meaning_ar' => 'سُمِّيت بقبيلة قريش سدنة البيت الحرام.',
        'summary_ar' => 'تذكّر قريشاً بنعمة الله في تأمين رحلتي الشتاء والصيف، وتدعوهم: فليعبدوا رب هذا البيت الذي أطعمهم من جوع وآمنهم من خوف.',
    ],
    107 => [
        'meaning_en' => "Al-Ma'un (The Small Kindnesses): named after the small acts of assistance withheld by the hypocritical.",
        'summary_en' => 'Identifies the denier of the Judgment as the one who repulses the orphan and does not encourage feeding the poor, and threatens woe upon those who pray heedlessly, who perform deeds to be seen, and who withhold even small kindnesses.',
        'meaning_ar' => 'سُمِّيت بالماعون، وهو ما يتعاون الناس به من صغائر العون الذي يمنعه المراؤون.',
        'summary_ar' => 'تعرّف المكذب بالدين: فذلك الذي يدُع اليتيم ولا يحض على طعام المسكين، وتتوعد بالويل المصلين الساهين عن صلاتهم الذين يراؤون ويمنعون الماعون.',
    ],
    108 => [
        'meaning_en' => 'Al-Kawthar (The Abundance): named after al-Kawthar, the river granted to the Prophet in Paradise — the shortest surah of the Quran.',
        'summary_en' => 'Consoles the Prophet after he was taunted as cut off without male heirs: We have granted you abundance, so pray to your Lord and sacrifice — indeed your enemy is the one cut off.',
        'meaning_ar' => 'سُمِّيت بالكوثر، النهر الذي أُعطيه النبي ﷺ في الجنة — وهي أقصر سور القرآن.',
        'summary_ar' => 'تواسي النبي ﷺ بعد أن عيّره المشركون بأنه أبتر: إنا أعطيناك الكوثر، فصل لربك وانحر — إن شانئك هو الأبتر.',
    ],
    109 => [
        'meaning_en' => 'Al-Kafirun (The Disbelievers): named after its address to the disbelievers who proposed alternating worship.',
        'summary_en' => 'The decisive disavowal of compromise in creed: when Quraysh offered to worship Allah a year if the Prophet worshipped their gods a year, it was revealed — I do not worship what you worship... for you is your religion, and for me is mine.',
        'meaning_ar' => 'سُمِّيت بخطابها للكافرين الذين عرضوا التناوب في العبادة.',
        'summary_ar' => 'البراءة الحاسمة من المساومة في العقيدة: لما عرضت قريش أن يعبدوا الله عاماً ويعبد النبي آلهتهم عاماً نزلت: لا أعبد ما تعبدون... لكم دينكم ولي دين.',
    ],
    110 => [
        'meaning_en' => 'An-Nasr (The Divine Support): named after the victory of Allah — the conquest of Mecca; among the last complete surahs revealed.',
        'summary_en' => "Announces the coming of Allah's help and the conquest, with people entering the religion of Allah in multitudes, and directs the Prophet to glorify his Lord's praise and seek His forgiveness — understood by the companions as heralding the approach of his passing.",
        'meaning_ar' => 'سُمِّيت بنصر الله، وهو فتح مكة؛ وهي من آخر السور نزولاً كاملة.',
        'summary_ar' => 'تعلن مجيء نصر الله والفتح ودخول الناس في دين الله أفواجاً، وتوجه النبي ﷺ إلى التسبيح بحمد ربه واستغفاره — وقد فهم منها كبار الصحابة نعيَ النبي ﷺ واقتراب أجله.',
    ],
    111 => [
        'meaning_en' => "Al-Masad (The Palm Fiber): named after the rope of palm fiber around the neck of Abu Lahab's wife; also called al-Lahab.",
        'summary_en' => "Pronounces ruin upon Abu Lahab, the Prophet's uncle who led the hostility against him: his wealth will not avail him; he will burn in a flaming fire, and his wife, the carrier of firewood of slander, with a rope of palm fiber upon her neck.",
        'meaning_ar' => 'سُمِّيت بحبل المسد في جيد امرأة أبي لهب، وتسمى أيضاً سورة اللهب.',
        'summary_ar' => 'تقضي بالتباب على أبي لهب، عم النبي ﷺ وقائد العداوة له: ما أغنى عنه ماله وما كسب، سيصلى ناراً ذات لهب، وامرأته حمالة الحطب في جيدها حبل من مسد.',
    ],
    112 => [
        'meaning_en' => "Al-Ikhlas (The Sincerity): named for its pure declaration of Allah's oneness, free of any partner or likeness.",
        'summary_en' => 'The creed of Islam in four verses — Say: He is Allah, the One; Allah, the Eternal Refuge; He neither begets nor is born, nor is there to Him any equivalent — described by the Prophet as equal to a third of the Quran.',
        'meaning_ar' => 'سُمِّيت بالإخلاص لتجريدها توحيد الله من كل شريك وشبيه.',
        'summary_ar' => 'عقيدة الإسلام في أربع آيات: قل هو الله أحد، الله الصمد، لم يلد ولم يولد، ولم يكن له كفواً أحد — وقد أخبر النبي ﷺ أنها تعدل ثلث القرآن.',
    ],
    113 => [
        'meaning_en' => "Al-Falaq (The Daybreak): named after the daybreak by whose Lord refuge is sought; the first of the two surahs of refuge (al-Mu'awwidhatayn).",
        'summary_en' => 'Teaches seeking refuge with the Lord of daybreak from the evil of what He created, from darkness when it settles, from the blowers on knots who practice sorcery, and from the envier when he envies.',
        'meaning_ar' => 'سُمِّيت بالفلق الذي يُستعاذ بربه، وهي أولى المعوذتين.',
        'summary_ar' => 'تعلّم الاستعاذة برب الفلق من شر ما خلق، ومن شر غاسق إذا وقب، ومن شر النفاثات في العقد، ومن شر حاسد إذا حسد.',
    ],
    114 => [
        'meaning_en' => 'An-Nas (Mankind): named after mankind, repeated five times in its verses; the second of the two surahs of refuge and the seal of the Quran.',
        'summary_en' => 'Teaches seeking refuge with the Lord, King and God of mankind from the evil of the retreating whisperer who whispers into the breasts of mankind, from among the jinn and mankind — closing the Quran with the fortress of refuge in Allah.',
        'meaning_ar' => 'سُمِّيت بالناس المتكرر ذكرهم خمس مرات فيها، وهي ثانية المعوذتين وخاتمة القرآن.',
        'summary_ar' => 'تعلّم الاستعاذة برب الناس ملك الناس إله الناس من شر الوسواس الخناس الذي يوسوس في صدور الناس، من الجنة والناس — فيُختم القرآن بحصن الالتجاء إلى الله.',
    ],
];
